-- ---------- 幂等清理 ----------
DELETE FROM `erp_product` WHERE `tenant_id` = 2001 AND `material_code` IN ('CP-1001','CP-1002','CP-1003','CP-1006','CP-1007','CP-1008','CP-1004','CP-1005','CP-2001','CP-2002','CP-3001','CP-3002','CP-3003','CP-4001','CP-4002','CP-5001','CP-5002','CP-5003','CP-6001','CP-6002','CP-6003','CP-6004','CP-7001','CP-7002','CP-7003','CP-7004','CP-8001','CP-8002','CP-8003','CP-9001');
